using System;using NUnit.Framework;
namespace LighthouseKeepers.Net.Tests {
 public sealed class StationGuidanceTests {
  static readonly Type Gate=Type.GetType("LighthouseKeepers.WatchDemo.StationObjectiveGuidance, Assembly-CSharp",true),Step=Type.GetType("LighthouseKeepers.WatchDemo.KeeperStep, Assembly-CSharp",true);
  static bool Allows(string station,string label,string step,int bolt=0)=>(bool)Gate.GetMethod("Allows").Invoke(null,new[]{Enum.Parse(Gate.GetNestedType("Station"),station),(object)label,Enum.Parse(Step,step),bolt});
  [Test]public void StarterDoesNotExposeFuelOrPartnerAssist(){Assert.True(Allows("Engine","Starter timing instruction","Starter"));Assert.False(Allows("Engine","Fuel filling plate","Starter"));Assert.False(Allows("Engine","Start assist brass stencil","Starter"));Assert.True(Allows("Engine","Start assist brass stencil","HoldStarterAssist"));Assert.False(Allows("Engine","Starter timing instruction","HoldStarterAssist"));}
  [Test]public void PipeOnlyShowsActiveBoltOrValvesOwnRole(){Assert.True(Allows("Pipe","Chalk coupling B","TightenBolt",1));Assert.False(Allows("Pipe","Chalk coupling A","TightenBolt",1));Assert.True(Allows("Valve","Valve fixed instruction","HoldValve"));Assert.False(Allows("Pipe","Chalk coupling A","HoldValve"));Assert.False(Allows("Valve","Valve fixed instruction","TightenBolt"));}
  [Test]public void RadioShowsCurrentVerbAndNeverAnAnswerToReader(){foreach(string name in new[]{"1 POWER","Radio readout","Code label 0","Code label 1","Code label 2","Code label 3"})Assert.False(Allows("Radio",name,"ReadCode"));Assert.True(Allows("Radio","Main label","RadioPower"));Assert.False(Allows("Radio","Code label 0","RadioPower"));for(int i=0;i<4;i++)Assert.True(Allows("Radio","Code label "+i,"RadioCode"));Assert.True(Allows("Radio","Mic label","RadioTransmit"));Assert.False(Allows("Radio","Mic label","RadioCode"));}
  [Test]public void BeaconAndPanelOnlyExposeCurrentControl(){Assert.True(Allows("Beacon","Ignition label","BeaconLight"));Assert.False(Allows("Beacon","Wheel label","BeaconLight"));Assert.True(Allows("Beacon","Wheel label","KeepLight"));Assert.False(Allows("Beacon","Ignition label","KeepLight"));for(int i=0;i<4;i++)Assert.AreEqual(i==1,Allows("Panel","Circuit label "+i,"BeaconOn"));}
  [Test]public void NoStationInstructionsWhileFetchingToolsOrResting(){foreach(string step in new[]{"GrabWrench","GrabWalkie","GrabLantern","LanternWick","Sleep"})foreach(string station in new[]{"Pipe","Engine","Radio","Beacon","Panel","Valve"})foreach(string label in new[]{"Radio readout","Timed starter order","Beacon instructions","Valve fixed instruction","Fuel level"})Assert.False(Allows(station,label,step));}
 }
}
